create table if not exists public.estate_subscription_counters (estate_key text primary key, estate_code text not null unique, next_number bigint not null default 1, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table if not exists public.estate_subscriptions (id uuid primary key default gen_random_uuid(), subscription_number text not null unique, estate_id uuid null, estate_name text not null, estate_code text not null, user_id uuid null, order_id uuid null, payment_request_id uuid null, subscription_status text not null default 'pending', payment_plan text null, amount numeric(18,2) not null default 0, subscribed_at timestamptz not null default now(), created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create unique index if not exists estate_subscriptions_estate_order_uidx on public.estate_subscriptions(estate_id,order_id) where estate_id is not null and order_id is not null;
create index if not exists estate_subscriptions_number_idx on public.estate_subscriptions(subscription_number);
create index if not exists estate_subscriptions_estate_idx on public.estate_subscriptions(estate_id,estate_code,subscription_status);
create index if not exists estate_subscriptions_user_idx on public.estate_subscriptions(user_id);
insert into public.estate_subscription_counters(estate_key,estate_code) values ('precious_gardens','PGE'),('the_ambassadors','APG'),('hampton_court','HCE') on conflict (estate_key) do nothing;
create or replace function public.next_estate_subscription_number(_estate_key text,_estate_name text,_estate_code text) returns text language plpgsql security definer set search_path=public as $$ declare n bigint; code text; begin insert into public.estate_subscription_counters(estate_key,estate_code) values (_estate_key,_estate_code) on conflict (estate_key) do nothing; select next_number,estate_code into n,code from public.estate_subscription_counters where estate_key=_estate_key for update; update public.estate_subscription_counters set next_number=n+1,updated_at=now() where estate_key=_estate_key; return code||'/'||lpad(n::text,3,'0'); end; $$;
revoke all on function public.next_estate_subscription_number(text,text,text) from public;
create or replace function public.create_estate_subscription(_estate_key text,_estate_name text,_estate_code text,_estate_id uuid,_user_id uuid,_order_id uuid,_payment_request_id uuid,_amount numeric,_payment_plan text,_status text default 'pending') returns public.estate_subscriptions language plpgsql security definer set search_path=public as $$ declare existing public.estate_subscriptions; num text; begin if _order_id is not null then select * into existing from public.estate_subscriptions where order_id=_order_id limit 1; if existing.id is not null then return existing; end if; end if; num:=public.next_estate_subscription_number(_estate_key,_estate_name,_estate_code); insert into public.estate_subscriptions(subscription_number,estate_id,estate_name,estate_code,user_id,order_id,payment_request_id,subscription_status,payment_plan,amount) values(num,_estate_id,_estate_name,_estate_code,_user_id,_order_id,_payment_request_id,coalesce(_status,'pending'),_payment_plan,coalesce(_amount,0)) returning * into existing; return existing; end; $$;
revoke all on function public.create_estate_subscription(text,text,text,uuid,uuid,uuid,uuid,numeric,text,text) from public;
grant execute on function public.create_estate_subscription(text,text,text,uuid,uuid,uuid,uuid,numeric,text,text) to authenticated;
create or replace function public.search_estate_subscribers(_search text default null,_estate_code text default null,_status text default null) returns setof public.estate_subscriptions language sql security definer set search_path=public as $$ select s from public.estate_subscriptions s where public.admin_has_permission('admin:all',auth.uid()) or public.admin_has_permission('admin:manage_users',auth.uid()) or public.admin_has_permission('admin:approve_payments',auth.uid()) order by s.created_at desc $$;
revoke all on function public.search_estate_subscribers(text,text,text) from public;
grant execute on function public.search_estate_subscribers(text,text,text) to authenticated;
